const staticData = $getWorkflowStaticData('global');

if (!Array.isArray(staticData.contentHistory)) staticData.contentHistory = [];
if (!Number.isInteger(staticData.categoryIndex)) staticData.categoryIndex = 0;

const categories = [
  'science',
  'space',
  'animals',
  'human body',
  'psychology',
  'history',
  'technology',
  'nature',
  'geography',
  'inventions',
  'food origins',
  'language',
  'money and economics',
  'mysteries and unusual facts',
  'records and comparisons',
  'ocean',
  'weather and natural phenomena',
  'everyday objects',
  'transportation',
  'art and culture'
];

const history = staticData.contentHistory.slice(-100);

const previous = history.length
  ? history.map((x, i) => `${i + 1}. CATEGORY: ${x.category}\nTITLE: ${x.title}\nHOOK: ${x.hook}\nTOPIC: ${x.topic}`).join('\n')
  : 'No previous content exists yet.';

const output = [];

for (let i = 0; i < 10; i++) {
  const category = categories[(staticData.categoryIndex + i) % categories.length];

  const system = `You are an expert viral YouTube Shorts scriptwriter.

The channel publishes surprising, accurate and verifiable "Did You Know?" facts.

ASSIGNED CATEGORY:
${category}

Return ONLY one JSON object with EXACTLY these keys:

hook - one short pattern-interrupt sentence and the first narration line.
script - 70-90 English words. Start with the hook. Conversational, fast and punchy. Explain ONE genuinely surprising fact. End with a short question or follow-for-more line. No emojis, hashtags or stage directions.
subtitle_ar - a natural Arabic translation of the FULL narration, preserving meaning and suitable for on-screen subtitles.
title - maximum 90 characters and MUST end with " #Shorts".
description - 2-3 natural English sentences followed by a new line containing 5 relevant hashtags.
tags - array of 8-12 lowercase English keyword strings.
query - 1-2 word English stock-video search query matching the topic.
voice - exactly "af_bella".
topic - concise description of the core fact.
category - exactly the assigned category.

CONTENT RULES:
1. The fact must be substantially different from all previous content.
2. Never reuse a previous fact with different wording.
3. Never reuse or closely imitate a previous title.
4. Never reuse a previous hook.
5. Avoid multiple videos about the same narrow subject.
6. Stay inside the assigned category.
7. Prefer surprising facts that are easy to understand in under one minute.
8. The fact must be verifiable; do not invent statistics or fake historical claims.
9. Keep narration suitable for approximately 35-55 seconds.
10. One strong fact per video.
11. Arabic subtitles must be a real Arabic translation, not transliteration.

PREVIOUS CONTENT TO AVOID:
${previous}`;

  output.push({
    json: {
      batchNumber: i + 1,
      category,
      body: {
        model: 'llama-3.3-70b-versatile',
        temperature: 1.0,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: system },
          {
            role: 'user',
            content: `Generate ONE completely fresh ${category} Short. Respond with JSON only.`
          }
        ]
      }
    }
  });
}

staticData.categoryIndex = (staticData.categoryIndex + 10) % categories.length;

return output;

const output = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const input = items[i];
  const res = input.json;
  const content = res.choices?.[0]?.message?.content;

  if (!content) {
    throw new Error(`Groq returned no content for item ${i + 1}`);
  }

  let data;

  try {
    data = JSON.parse(content);
  } catch (error) {
    throw new Error(`Invalid Groq JSON for item ${i + 1}: ${content.slice(0, 600)}`);
  }

  const required = [
    'script',
    'subtitle_ar',
    'title',
    'hook',
    'topic',
    'description'
  ];

  for (const key of required) {
    if (!data[key]) {
      throw new Error(`Missing ${key} for item ${i + 1}`);
    }
  }

  data.tags = Array.isArray(data.tags) ? data.tags : [];
  data.voice = 'af_bella';
  data.query = data.query || 'nature';
  data.category = data.category || 'general';

  if (!data.title.toLowerCase().includes('#shorts')) {
    data.title = `${data.title.trim()} #Shorts`;
  }

  const wordCount = String(data.script)
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .length;

  if (wordCount < 65 || wordCount > 100) {
    throw new Error(`SCRIPT_LENGTH_REJECTED item ${i + 1}: ${wordCount} words`);
  }

  output.push({
    json: {
      ...data,
      batchNumber: i + 1
    }
  });
}

return output;

const staticData = $getWorkflowStaticData('global');

if (!Array.isArray(staticData.contentHistory)) {
  staticData.contentHistory = [];
}

const history = staticData.contentHistory;
const accepted = [];

function normalize(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/#shorts/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function words(text) {
  return new Set(
    normalize(text)
      .split(' ')
      .filter(w => w.length > 3)
  );
}

function similarity(a, b) {
  const A = words(a);
  const B = words(b);

  if (!A.size || !B.size) return 0;

  let intersection = 0;

  for (const word of A) {
    if (B.has(word)) intersection++;
  }

  return intersection / Math.max(1, Math.min(A.size, B.size));
}

for (const wrapper of $input.all()) {
  const item = wrapper.json;
  const candidate = [
    item.title,
    item.hook,
    item.topic,
    item.script
  ].join(' ');

  for (const old of history.slice(-100).concat(accepted)) {
    if (normalize(item.title) === normalize(old.title)) {
      throw new Error(`DUPLICATE_CONTENT_REJECTED: duplicate title in batch ${item.batchNumber}`);
    }

    if (normalize(item.hook) === normalize(old.hook)) {
      throw new Error(`DUPLICATE_CONTENT_REJECTED: duplicate hook in batch ${item.batchNumber}`);
    }

    if (similarity(item.topic, old.topic) >= 0.60) {
      throw new Error(`DUPLICATE_CONTENT_REJECTED: similar topic in batch ${item.batchNumber}`);
    }

    const oldContent = [
      old.title,
      old.hook,
      old.topic,
      old.script
    ].join(' ');

    if (similarity(candidate, oldContent) >= 0.58) {
      throw new Error(`DUPLICATE_CONTENT_REJECTED: similar content in batch ${item.batchNumber}`);
    }
  }

  accepted.push({
    title: item.title,
    hook: item.hook,
    topic: item.topic,
    script: item.script,
    query: item.query,
    category: item.category,
    createdAt: new Date().toISOString()
  });
}

history.push(...accepted);

while (history.length > 100) {
  history.shift();
}

return $input.all();

return $input.all().map((wrapper, index) => {
  const item = wrapper.json;
  const batchNumber = item.batchNumber || index + 1;
  const runId = `${String($execution.id || Date.now())}_${batchNumber}`;
  const runDir = `/data/${runId}`;

  const job = {
    script: item.script,
    subtitle_ar: item.subtitle_ar,
    query: item.query,
    voice: 'af_bella'
  };

  const jobB64 = Buffer
    .from(JSON.stringify(job), 'utf8')
    .toString('base64');

  return {
    json: {
      ...item,
      batchNumber,
      runId,
      runDir,
      jobB64
    }
  };
});
